import{_ as t,o as a,c as e,a2 as r}from"./chunks/framework.A5mep7Fe.js";const h=JSON.parse('{"title":"🔌 05 · 嵌入式与端侧 AI（AIoT / Edge AI）","description":"","frontmatter":{},"headers":[],"relativePath":"06-开发岗-编程语言与工程/05-嵌入式.md","filePath":"06-开发岗-编程语言与工程/05-嵌入式.md","lastUpdated":1786806808000}'),i={name:"06-开发岗-编程语言与工程/05-嵌入式.md"};function l(n,o,s,c,d,g){return a(),e("div",null,[...o[0]||(o[0]=[r('<h1 id="🔌-05-·-嵌入式与端侧-ai-aiot-edge-ai" tabindex="-1">🔌 05 · 嵌入式与端侧 AI（AIoT / Edge AI） <a class="header-anchor" href="#🔌-05-·-嵌入式与端侧-ai-aiot-edge-ai" aria-label="Permalink to &quot;🔌 05 · 嵌入式与端侧 AI（AIoT / Edge AI）&quot;">​</a></h1><blockquote><p>把 AI 放到设备端：手机、车载、IoT、机器人。端侧推理是「隐私 + 低延迟 + 离线」的关键方向。</p></blockquote><hr><h2 id="一、核心考点" tabindex="-1">一、核心考点 <a class="header-anchor" href="#一、核心考点" aria-label="Permalink to &quot;一、核心考点&quot;">​</a></h2><ul><li><strong>MCU/RTOS</strong>：单片机（STM32 等）、实时操作系统（FreeRTOS）、中断/定时器。</li><li><strong>交叉编译</strong>：在 PC 编译、在 ARM/嵌入式设备运行。</li><li><strong>内存与算力限制</strong>：KB~MB 级内存、无 MMU、低功耗约束。</li><li><strong>外设与总线</strong>：I2C/SPI/UART、传感器采集。</li><li><strong>C/C++ 主导</strong>，部分用 Rust（安全）、MicroPython（原型）。</li></ul><h2 id="二、端侧-ai-结合点" tabindex="-1">二、端侧 AI 结合点 <a class="header-anchor" href="#二、端侧-ai-结合点" aria-label="Permalink to &quot;二、端侧 AI 结合点&quot;">​</a></h2><ul><li><strong>模型压缩</strong>：量化（INT8/INT4）、剪枝、蒸馏，使模型适配端侧。</li><li><strong>端侧推理框架</strong>：NCNN、MNN、TFLite、TensorRT-LLM（边缘 GPU）、ONNX Runtime Mobile。</li><li><strong>NPU/专用加速</strong>：利用芯片 AI 加速器（如手机 NPU、地平线/昇腾）。</li><li><strong>应用场景</strong>：语音唤醒、人脸识别、手势、车载感知、工业质检。</li></ul><h2 id="三、高频追问" tabindex="-1">三、高频追问 <a class="header-anchor" href="#三、高频追问" aria-label="Permalink to &quot;三、高频追问&quot;">​</a></h2><p><strong>Q1：端侧部署为什么必须量化？</strong></p><blockquote><p>端侧算力/内存/功耗有限，FP32 模型跑不动；INT8/INT4 量化大幅降资源且精度损失可控，是端侧落地关键。</p></blockquote><p><strong>Q2：端侧和云端推理怎么分工？</strong></p><blockquote><p>云端：大模型、复杂任务；端侧：低延迟/隐私/离线的小模型（唤醒词、简单识别）。常「端侧预处理 + 云端重推理」混合。</p></blockquote><p><strong>Q3：嵌入式实时性如何保证？</strong></p><blockquote><p>用 RTOS 保证确定时延、优先级调度、中断响应；避免在关键路径做重计算；用 DMA 等硬件卸载。</p></blockquote><hr><p>➡️ 返回：<a href="./README">06-开发岗-编程语言与工程 README</a> ｜ 进入：<a href="./../07-开发岗-前后端与全栈/README">07-开发岗-前后端与全栈</a></p>',16)])])}const u=t(i,[["render",l]]);export{h as __pageData,u as default};
